// Wild Voronoi — kd-tree Study

// ------------ Config ----------
const CELL_SIZE = 8;
const N = 50;

// ------------ Site Class ----------
class Site {
  constructor() {
    // position
    this.x = random(width);
    this.y = random(height);

    // velocity
    this.vx = random(-2, 2);
    this.vy = random(-2, 2);

    // color
    this.c = color(random(255), random(255), random(255));
  }

  update() {
    // update position
    this.x += this.vx;
    this.y += this.vy;

    // bounce on borders
    if (this.x < 0 || this.x > width) this.vx *= -1;
    if (this.y < 0 || this.y > height) this.vy *= -1;
  }
}

// ------------ kd-tree Node ------------
class Node {
  constructor(site, axis, left, right) {
    this.site = site;   // stored site
    this.axis = axis;   // 0 = x, 1 = y
    this.left = left;   // left subtree
    this.right = right; // right subtree
  }
}

// ------------ Build kd-tree ------------
function buildKDTree(sites, depth = 0) {
  if (sites.length === 0) return null;

  const axis = depth & 1; // 0 or 1

  // sort sites by x or y axis
  const sorted = sites
    .slice()
    .sort((a, b) => (axis === 0 ? a.x - b.x : a.y - b.y));

  const mid = floor(sorted.length / 2);

  return new Node(
    sorted[mid],
    axis,
    buildKDTree(sorted.slice(0, mid), depth + 1),
    buildKDTree(sorted.slice(mid + 1), depth + 1)
  );
}

// ------------ Nearest Neighbor Search ------------
function nearest(node, target, best = { site: null, dist: Infinity }) {
  if (!node) return best;

  // squared distance to current node site
  const dx = node.site.x - target.x;
  const dy = node.site.y - target.y;
  const d2 = dx * dx + dy * dy;

  // update best if needed
  if (d2 < best.dist) best = { site: node.site, dist: d2 };

  const axis = node.axis;
  const diff = axis === 0 ? target.x - node.site.x : target.y - node.site.y;

  // choose branch
  const near = diff < 0 ? node.left : node.right;
  const far  = diff < 0 ? node.right : node.left;

  // search nearer branch
  best = nearest(near, target, best);

  // check farther branch if needed
  if (diff * diff < best.dist) {
    best = nearest(far, target, best);
  }

  return best;
}

// ------------ Main Sketch ------------
let sites = [];
let rootNode;

function setup() {
  createCanvas(640, 640);
  rectMode(CORNER);
  noStroke();

  // generate sites
  for (let i = 0; i < N; i++) {
    sites.push(new Site());
  }

  // initial kd-tree
  rootNode = buildKDTree(sites);
}

function draw() {
  background(0);

  // update motion
  for (const s of sites) s.update();

  // rebuild kd-tree after motion
  rootNode = buildKDTree(sites);

  // draw Voronoi using grid cells
  for (let y = 0; y < height; y += CELL_SIZE) {
    for (let x = 0; x < width; x += CELL_SIZE) {
      const nn = nearest(rootNode, { x, y });
      fill(nn.site.c);
      rect(x, y, CELL_SIZE - 1, CELL_SIZE - 1);
    }
  }
}


